      <Pre>{"docker run -d --name granite-4.2-8b \\\n  --device /dev/kfd --device /dev/dri --group-add video --group-add render \\\n  --security-opt seccomp=unconfined --ipc host \\\n  -v ~/models:/models -p 8000:8000 \\\n  -e HIP_VISIBLE_DEVICES=0 -e LD_LIBRARY_PATH=/app:/opt/rocm/lib -e HSA_NO_SCRATCH_RECLAIM=1 -e HIP_FORCE_DEV_KERNARG=1 \\\n  --entrypoint /bin/bash ghcr.io/inferstation/llama-rocm-w7900:commit-29b52d398b29 \\\n  -lc \"exec llama-server -m /models/granite-4.2-8b/granite-4.2-8b-Q4_K_M.gguf -ngl 999 \\\n    -fa on --host 0.0.0.0 --port 8000 -c 32768 -np 32 --cache-ram 0\""}</Pre>
