      <Pre>{"curl http://localhost:8000/v1/chat/completions \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"model\": \"local\", \"messages\": [{\"role\": \"user\", \"content\": \"用一句话介绍一下你自己。\"}], \"max_tokens\": 128}'"}</Pre>
